#[inline(always)]
pub(crate) fn sin_kernel_f64(x: f64) -> f64 {
    let ax = x.abs();
    if ax <= SIN_SEG_BOUNDS_F64[0] {
        let z = x * x;
        x * eval_horner_f64_slice(z, &COEFFS64_SEG0)
    } else if ax <= SIN_SEG_BOUNDS_F64[1] {
        let z = x * x;
        x * eval_horner_f64_slice(z, &COEFFS64_SEG1)
    } else if ax <= SIN_SEG_BOUNDS_F64[2] {
        let z = x * x;
        x * eval_horner_f64_slice(z, &COEFFS64_SEG2)
    } else if ax <= SIN_SEG_BOUNDS_F64[3] {
        let z = x * x;
        x * eval_horner_f64_slice(z, &COEFFS64_SEG3)
    } else if ax <= SIN_SEG_BOUNDS_F64[4] {
        let z = x * x;
        x * eval_horner_f64_slice(z, &COEFFS64_SEG4)
    } else {
        let z = x * x;
        x * eval_horner_f64_slice(z, &COEFFS64_SEG4)
    }
}
