#[inline]
pub fn sin(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }
    let (r, q) = rem_pio2_f64(x);
    match q {
        0 => k_sin_f64(r),
        1 => k_cos_f64(r),
        2 => -k_sin_f64(r),
        3 => -k_cos_f64(r),
        _ => unreachable!(),
    }
}

